<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import * as echarts from 'echarts'
import { storeToRefs } from 'pinia'
import { useUraniumDemoStore } from '@/stores/scnet/useUraniumDemoStore'

const store = useUraniumDemoStore(); const { selectedExperiment } = storeToRefs(store)
const strategy = ref('compare'); const shockSize = ref(20); const chartRef = ref(null); let chart
const fallbackTimeline = [{year:2024,unmet_demand_tU:260,inventory_coverage_years:.93,active_events:['铀价与哈酸短缺']},{year:2025,unmet_demand_tU:250,inventory_coverage_years:.98,active_events:['去俄化采购竞争升温']},{year:2026,unmet_demand_tU:150,inventory_coverage_years:1.02,active_events:['新增矿山投产']},{year:2027,unmet_demand_tU:260,inventory_coverage_years:1.04,active_events:['高需求情景下生产短缺']},{year:2028,unmet_demand_tU:410,inventory_coverage_years:1.01,active_events:['美国禁俄铀完全生效']}]
const timeline = computed(() => selectedExperiment.value?.result?.timeline?.length ? selectedExperiment.value.result.timeline : fallbackTimeline)
const shockYear = ref(2027)
const currentWindow = computed(() => timeline.value.find(item => item.year === shockYear.value) || timeline.value[0] || fallbackTimeline[0]); const currentYear = computed(() => shockYear.value); const currentEvent = computed(() => currentWindow.value?.active_events?.[0] || '稳态采购与库存校准'); const experimentLabel = computed(() => selectedExperiment.value?.title || selectedExperiment.value?.experiment_id || '当前铀供应链实验')
const months = Array.from({length:21},(_,i)=>`月${i+1}`); const shockIndex = computed(() => Math.min(16,Math.max(4,timeline.value.findIndex(item=>item.year===shockYear.value)*3+5)))
const demand = computed(() => months.map((_,i)=>i===shockIndex.value?100+shockSize.value:i===shockIndex.value+1?108:100))
const makeSeries=(factor,response,controlled=false)=>demand.value.map((value,i)=>{const delay=Math.max(i-shockIndex.value,0);const pulse=i===shockIndex.value?value*(factor-1):delay===1?value*(factor-1)*response:delay===2?value*(factor-1)*response*.45:0;return Math.round(value+pulse+(controlled?(i%4-1)*2:(i%3-1)*4))})
const baseline=computed(()=>({trade:makeSeries(1.35,.9),conversion:makeSeries(1.85,.82),supplier:makeSeries(2.65,.72)})); const system=computed(()=>({trade:makeSeries(1.2,.65,true),conversion:makeSeries(1.38,.52,true),supplier:makeSeries(1.7,.4,true)}))
const amplifications=computed(()=>{const values=strategy.value==='baseline'?[1.35,1.85,2.65]:[1.2,1.38,1.7];return ['贸易商','转化节点','铀供应商'].map((name,i)=>({name,value:values[i],color:['#3b82f6','#8b5cf6','#e07a45'][i],detail:i===2?'上游峰值最明显':'相对终端需求'}))})
const metrics=computed(()=>[{label:'最大放大倍数',value:`${Math.max(...amplifications.value.map(i=>i.value)).toFixed(2)}×`,hint:strategy.value==='baseline'?'基线采购':'协同调度'},{label:'当前需求缺口',value:`${currentWindow.value?.unmet_demand_tU||0} tU`,hint:`${currentYear.value} 年压力窗口`},{label:'库存覆盖',value:`${Number(currentWindow.value?.inventory_coverage_years||0).toFixed(2)} 年`,hint:'来自当前铀实验'},{label:'预计恢复时间',value:strategy.value==='baseline'?'5 个月':'3 个月',hint:'回到冲击前 ±5%'}])
const interventions=computed(()=>[{no:'01',title:'采购信号平滑',text:'把年度需求缺口拆成滚动补库信号，降低贸易商一次性追单。',result:strategy.value==='baseline'?'未启用':'已启用'},{no:'02',title:'双通道分配',text:'在哈萨克陆路、加拿大和纳米比亚海运之间分摊上游暴露。',result:strategy.value==='baseline'?'单通道敏感':'多源分摊'},{no:'03',title:'库存阈值联动',text:'以库存覆盖和缺口触发补库，而不是只根据当期价格追涨。',result:strategy.value==='baseline'?'被动补库':'阈值触发'}])
const formatPercent = (value) => Number.isFinite(Number(value)) ? `${(Number(value) * 100).toFixed(1)}%` : '—'
const formatDecimal = (value) => Number.isFinite(Number(value)) ? Number(value).toFixed(3) : '—'
const comparisonRows=computed(()=>[
  {label:'最大放大倍数',note:'供应商层级',baseline:'2.65×',system:'1.70×',delta:'↓ 35.8%'},
  {label:'需求缺口',note:`${shockYear.value} 年`,baseline:`${currentWindow.value?.unmet_demand_tU || 0} tU`,system:`${Math.round((currentWindow.value?.unmet_demand_tU || 0) * .62)} tU`,delta:'↓ 38.0%'},
  {label:'库存覆盖',note:'年度期末',baseline:`${Number(currentWindow.value?.inventory_coverage_years || 0).toFixed(2)} 年`,system:`${(Number(currentWindow.value?.inventory_coverage_years || 0) + .12).toFixed(2)} 年`,delta:'↑ 0.12 年'},
  {label:'恢复时间',note:'回到冲击前 ±5%',baseline:'5 个月',system:'3 个月',delta:'↓ 2 个月'}
])
function option(){const lines=[{name:'终端需求',data:demand.value,color:'#334155',dash:true}];const add=(prefix,data,colors)=>{if(!data)return;[['贸易商',data.trade],['转化节点',data.conversion],['铀供应商',data.supplier]].forEach(([name,values],i)=>lines.push({name:`${prefix}${name}`,data:values,color:colors[i]}))};add(strategy.value==='compare'?'基线 · ':'',strategy.value==='system'?null:baseline.value,['#93c5fd','#a78bfa','#fdba74']);add(strategy.value==='compare'?'协同 · ':'',strategy.value==='baseline'?null:system.value,['#2563eb','#7c3aed','#ea580c']);return{tooltip:{trigger:'axis'},legend:{top:0,type:'scroll'},grid:{left:48,right:18,top:38,bottom:30},xAxis:{type:'category',data:months},yAxis:{type:'value',name:'指数',min:80,max:300},series:lines.map(s=>({name:s.name,type:'line',smooth:true,data:s.data,symbol:'circle',symbolSize:5,lineStyle:{color:s.color,type:s.dash?'dashed':'solid',width:2},itemStyle:{color:s.color},markLine:s.name==='终端需求'?{silent:true,symbol:'none',lineStyle:{color:'#d97706',type:'dashed'},data:[{xAxis:months[shockIndex.value]}]}:undefined}))}}
function render(){if(!chartRef.value)return;if(!chart)chart=echarts.init(chartRef.value);chart.setOption(option(),true);chart.resize()}
watch([strategy,shockSize,shockYear],()=>nextTick(render));watch(selectedExperiment,()=>nextTick(render));onMounted(()=>{store.ensureInitialized().catch(()=>{});nextTick(render)});onBeforeUnmount(()=>chart?.dispose())
</script>

